curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: <TOKEN>" \
  -d '{
    "query": "query { issue(identifier: \"WEB-5\") { id identifier title comments(first: 200) { nodes { id body resolved resolvedAt parent { id } createdBy { id name } resolvedBy { id name } } } } }"
  }'

